#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    long long value;
    long long count;
} Entry;

int compare_entries(const void *lhs, const void *rhs) {
    const Entry *a = (const Entry *)lhs;
    const Entry *b = (const Entry *)rhs;
    if (a->count != b->count) {
        return (a->count > b->count) ? -1 : 1;
    }
    if (a->value != b->value) {
        return (a->value < b->value) ? -1 : 1;
    }
    return 0;
}

long long* topKFrequent(const long long* arr, long long arr_len, long long k, long long* result_len) {
    if (k <= 0 || arr_len == 0) {
        *result_len = 0;
        long long* empty = malloc(sizeof(long long));
        return empty;
    }

    Entry* entries = malloc(arr_len * sizeof(Entry));
    long long entries_count = 0;

    for (long long i = 0; i < arr_len; i++) {
        bool found = false;
        for (long long j = 0; j < entries_count; j++) {
            if (entries[j].value == arr[i]) {
                entries[j].count++;
                found = true;
                break;
            }
        }
        if (!found) {
            entries[entries_count].value = arr[i];
            entries[entries_count].count = 1;
            entries_count++;
        }
    }

    qsort(entries, entries_count, sizeof(Entry), compare_entries);

    long long return_k = k;
    if (return_k > entries_count) {
        return_k = entries_count;
    }

    long long* result = malloc(return_k * sizeof(long long));
    for (long long i = 0; i < return_k; i++) {
        result[i] = entries[i].value;
    }

    free(entries);
    *result_len = return_k;
    return result;
}

