import java.util.*;

public class Solution {
    public static int[] topKFrequent(int[] arr, int k) {
        if (arr.length == 0 || k <= 0) {
            return new int[0];
        }

        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : arr) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        List<Map.Entry<Integer, Integer>> entries = new ArrayList<>(freqMap.entrySet());

        entries.sort((lhs, rhs) -> {
            int freqCompare = Integer.compare(rhs.getValue(), lhs.getValue());
            if (freqCompare != 0) {
                return freqCompare;
            }
            return Integer.compare(lhs.getKey(), rhs.getKey());
        });

        int[] result = new int[Math.min(k, entries.size())];
        for (int i = 0; i < result.length; i++) {
            result[i] = entries.get(i).getKey();
        }

        return result;
    }

    private static String arrayToString(int[] arr) {
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        for (int i = 0; i < arr.length; i++) {
            sb.append(arr[i]);
            if (i < arr.length - 1) {
                sb.append(", ");
            }
        }
        sb.append("]");
        return sb.toString();
    }

    public static void main(String[] args) {
        int[][] testCases = {
            {1, 1, 1, 2, 2, 3},
            {1},
            {},
            {4, 1, -1, 2, -1, 2, 3},
            {5, 5, 5, 5, 5, 5, 5}
        };
        int[] ks = {2, 1, 3, 3, 1};

        for (int i = 0; i < testCases.length; i++) {
            int[] result = topKFrequent(testCases[i], ks[i]);
            System.out.println(arrayToString(result));
        }
    }
}
